from pathlib import Path
import json,re

event_id='1791185669-30977cb32a12'
base=Path.home()/'.local/share/prediction-chat-bridge'
raw=None
where=None
for dname in ('sent','inflight','outbox'):
    p=base/dname/f'{event_id}.json'
    if p.is_file():
        try:
            obj=json.loads(p.read_text(encoding='utf-8',errors='replace'))
            raw=str(obj.get('message') or '')
            where=str(p)
            break
        except Exception:
            pass

if raw is None:
    print('PROD_STAGED_DIFF=RAW_EVENT_MISSING')
    raise SystemExit(42)

payload=None
for ln in raw.splitlines():
    if ln.startswith('PRODUCTION_DIFF_INSPECT '):
        try:
            payload=json.loads(ln.split(' ',1)[1])
            break
        except Exception:
            pass

if payload is None:
    m=re.search(r'PRODUCTION_DIFF_INSPECT\s+(\{.*?\})(?:\n[A-Z0-9_]+=|\Z)',raw,re.S)
    if m:
        try: payload=json.loads(m.group(1))
        except Exception: pass

if payload is None:
    print('PROD_STAGED_DIFF=PAYLOAD_NOT_FOUND || FILE='+where)
    raise SystemExit(42)

diff=str(payload.get('diff') or '')
files=[]
stats={}
cur=None
for line in diff.splitlines():
    if line.startswith('diff --git a/'):
        cur=line.split(' b/',1)[-1]
        if cur not in stats:
            files.append(cur);stats[cur]={'a':0,'d':0,'sig':[]}
    elif cur and line.startswith('+') and not line.startswith('+++'):
        stats[cur]['a']+=1
        s=line[1:].strip()
        if (re.match(r'(def |class |async def )',s) or re.match(r'[A-Z][A-Z0-9_]{2,}\s*=',s)) and len(stats[cur]['sig'])<4:
            stats[cur]['sig'].append('+'+s[:120])
    elif cur and line.startswith('-') and not line.startswith('---'):
        stats[cur]['d']+=1
        s=line[1:].strip()
        if (re.match(r'(def |class |async def )',s) or re.match(r'[A-Z][A-Z0-9_]{2,}\s*=',s)) and len(stats[cur]['sig'])<4:
            stats[cur]['sig'].append('-'+s[:120])

parts=[]
for f in files:
    st=stats[f]
    sig=' ; '.join(st['sig'])
    parts.append(f"{f}[+{st['a']}/-{st['d']}]" + (f"{{{sig}}}" if sig else ''))

print('PROD_STAGED_DIFF='+' | '.join(parts)[:3200]+' || FILE='+where,flush=True)
raise SystemExit(42)
